modelSource:
cube('analytics_nonadditive_totals', {
    sql: "SELECT * FROM analytics_nonadditive_totals WHERE channel = 'keep'",
    dimensions: { id: { sql: 'id', type: 'number', primary_key: true, public: true },
      region: { sql: 'region', type: 'string' }, person: { sql: 'person', type: 'string' } },
    measures: {
      average: { sql: 'amount', type: 'avg' },
      samples: { type: 'count', filters: [{ sql: `${CUBE}.amount IS NOT NULL` }] },
      distinct: { sql: 'person', type: 'countDistinct' },
      total: { sql: 'amount', type: 'sum' },
      weighted_native: { type: 'number', sql: `${total} / NULLIF(${samples}, 0)` }
    }
  });

setupSQL:
CREATE TABLE analytics_nonadditive_totals(id integer PRIMARY KEY, region text, person text, channel text, amount double precision);
    INSERT INTO analytics_nonadditive_totals SELECT -id, 'A', CASE WHEN id % 2 = 0 THEN 'p2' ELSE 'p1' END,
      'keep', 10 FROM generate_series(1,9) AS input(id);
    INSERT INTO analytics_nonadditive_totals VALUES (-10,'B','p2','keep',100),(-11,'B','p3','keep',NULL),
      (-12,'Z',NULL,'keep',NULL),(-99,'clipped','secret','exclude',999);
    INSERT INTO analytics_nonadditive_totals SELECT id, LPAD(id::text,8,'0'), 'person_' || id::text, 'keep', id
      FROM generate_series(1,60001) AS input(id);
